package core.game.node.entity.player;import kotlin.Unit;import kotlin.jvm.functions.Function1;import java.util.*;import core.game.node.entity.Entity;public class Player extends Entity{public final Map<String,Function1<Player,Unit>> logoutListeners=new HashMap<String,Function1<Player,Unit>>(){public Function1<Player,Unit> put(String k,Function1<Player,Unit> v){oracle.Support.emit("logoutAdd");return super.put(k,v);}public Function1<Player,Unit> remove(Object k){oracle.Support.emit("logoutRemove");return super.remove(k);}};public Packets getPacketDispatch(){return new Packets();}public Diary getAchievementDiaryManager(){return new Diary();}public static class Packets{public void sendMessage(String s){oracle.Support.emit("message",s);}}public static class Diary{public void finishTask(Player p,core.game.node.entity.player.link.diary.DiaryType d,int level,int task){oracle.Support.emit("diary",d.name(),level,task);}}}